import json
LANGS=['en','es','ca']
out={l:{} for l in LANGS}
for d in (S,W):
    for k,v in d.items():
        for i,l in enumerate(LANGS): out[l][k]=v[i].replace("\\'","'")
plur={l:{} for l in LANGS}
for k,v in P.items():
    for i,l in enumerate(LANGS): plur[l][k]=list(v[i])
js='// Generado desde las cadenas de Android (scripts/strings); no editar a mano.\nwindow.TANSU_I18N = '+json.dumps({'s':out,'p':plur},ensure_ascii=False,indent=0)+';\n'
os.makedirs(str(ROOT/'web'),exist_ok=True)
open(str(ROOT/'web/i18n.js'),'w').write(js)
